<?php
$pageTitle = 'Reserve catering';
$packages = $packages ?? []; $items = $items ?? []; $packageOptions = $packageOptions ?? [];
$oldReservation = is_array($reservationOld ?? null) ? $reservationOld : [];
$oldValue = static function (string $key, string $default = '') use ($oldReservation): string { $value = $oldReservation[$key] ?? $default; return rc_e(is_scalar($value) ? (string) $value : $default); };
$oldItems = is_array($oldReservation['items'] ?? null) ? $oldReservation['items'] : [];
$oldOptions = is_array($oldReservation['options'] ?? null) ? $oldReservation['options'] : [];
$oldOptionSelected = static function (string $group, int $id, bool $default = false) use ($oldOptions): bool {
    if (!array_key_exists($group, $oldOptions)) return $default;
    $values = is_array($oldOptions[$group]) ? $oldOptions[$group] : [$oldOptions[$group]];
    return in_array((string) $id, array_map(static fn ($value) => is_scalar($value) ? (string) $value : '', $values), true);
};
$requestedPackage = (int) ($requestedPackage ?? 0);
if ($requestedPackage < 1) $requestedPackage = (int) ($_GET['package'] ?? $oldReservation['package_id'] ?? 0);
$initialOrderType = '';
foreach ($packages as $p) if ((int)$p['package_id']===$requestedPackage) { $initialOrderType = in_array(($p['package_type']??'custom'), ['packed_meal','buffet','custom'], true) ? $p['package_type'] : 'custom'; break; }
if ($requestedPackage < 1) {
    $oldOrderType = (string) ($oldReservation['order_type'] ?? $_GET['order_type'] ?? '');
    if (in_array($oldOrderType, ['alacarte','packed_meal','buffet','custom'], true)) $initialOrderType = $oldOrderType;
}
$groups = [];
foreach ($packageOptions as $option) {
    if (($option['package_type'] ?? '') === 'packed_meal' && $option['component_type'] === 'rice') continue;
    $groups[(int)$option['package_id']][$option['option_group']][] = $option;
}
$componentOrder = ['main_dish'=>0,'side_dish'=>1,'dessert'=>2,'salad'=>3,'rice'=>4,'drink'=>5,'add_on'=>6,'other'=>7];
foreach ($groups as &$packageGroups) {
    uasort($packageGroups, static function ($a, $b) use ($componentOrder) { return ($componentOrder[$a[0]['component_type']] ?? 8) <=> ($componentOrder[$b[0]['component_type']] ?? 8); });
}
unset($packageGroups);
$unitLabels = ['tray_25_35pax'=>'Tray · serves 25–35','per_pc'=>'Per piece','per_box'=>'Per box','per_tray'=>'Per tray','per_layer'=>'Per layer','per_slice'=>'Per slice','per_person'=>'Per person','each'=>'Each'];
?>
