<div class="field field-wide" data-package-picker hidden><label for="package">Food package</label><select class="input-field" name="package_id" id="package"><option value="">Select a package</option><?php foreach ($packages as $package): ?><option value="<?= (int)$package['package_id'] ?>" data-package-type="<?= rc_e($package['package_type'] ?? 'custom') ?>" data-minimum="<?= max(1,(int)$package['minimum_guests']) ?>" data-maximum="<?= rc_e((string)($package['maximum_guests'] ?? '')) ?>" data-price="<?= rc_e($package['package_price']) ?>" data-pricing="<?= rc_e($package['price_type']) ?>" <?= $requestedPackage === (int)$package['package_id'] ? 'selected' : '' ?>><?= rc_e(($package['set_name'] ?? '') ?: $package['package_name']) ?> · <?= rc_money(rc_cents($package['package_price'])) ?> <?= $package['price_type']==='Per Person' ? '/ person' : 'package' ?></option><?php endforeach; ?></select><small class="package-empty-note" data-package-empty role="status" hidden>No active food packages are configured yet. Choose buffet or packed lunch, or ask the owner to add a food package under Owner → Packages.</small></div>
<div class="field"><label for="guest-count">Number of guests</label><input class="input-field" id="guest-count" name="guest_count" type="number" min="1" max="10000" value="<?= $oldValue('guest_count','50') ?>" required></div>
<?php foreach ($packages as $package): foreach ($groups[(int)$package['package_id']] ?? [] as $group=>$options): $isRequired=$options[0]['selection_rule']==='Required One'; $limit=$options[0]['component_type']==='add_on' ? 20 : (($options[0]['component_type']==='main_dish' && ($package['package_type']??'')==='packed_meal' && ($package['set_name']??'')==='Tier D') ? 2 : 1); ?>
<fieldset class="field field-wide package-options" data-package-options="<?= (int)$package['package_id'] ?>" data-option-limit="<?= $limit ?>" hidden><legend><?php if (($package['package_type']??'')==='buffet' && str_starts_with((string)$group,'Included: ')): ?><?= rc_e(ucwords(str_replace('_',' ',(string)$options[0]['component_type']))) ?> · included: <?= rc_e(substr((string)$group,10)) ?> · choose a replacement if desired<?php else: ?><?= rc_e(ucwords(str_replace('_',' ',(string)$options[0]['component_type']))) ?><?= $isRequired ? ' · choose one' : ' · choose up to '.$limit ?><?php endif; ?></legend><div class="option-grid"><?php foreach ($options as $option): $inputType=$isRequired ? 'radio' : 'checkbox'; $defaultSelection=($package['package_type']??'')==='buffet' && str_starts_with((string)$group,'Included: ') && strcasecmp((string)$option['name'],substr((string)$group,10))===0; $isSelected=$oldOptionSelected((string)$group,(int)$option['id'],$defaultSelection); ?><label class="option-choice"><input type="<?= $inputType ?>" name="options[<?= rc_e($group) ?>]<?= $inputType==='checkbox'?'[]':'' ?>" value="<?= (int)$option['id'] ?>" data-charge="<?= rc_e($option['additional_charge']) ?>" data-charge-type="<?= rc_e($option['charge_type'] ?? 'per_event') ?>" <?= $isRequired ? 'required' : '' ?> <?= $isSelected?'checked':'' ?>><span><strong><?= rc_e($option['name']) ?></strong><small><?= rc_e($option['description'] ?: $option['category']) ?><?= rc_cents($option['additional_charge']) > 0 ? ' · +' . rc_money(rc_cents($option['additional_charge'])) . (($option['charge_type']??'')==='per_person'?' per person':'') : '' ?></small></span></label><?php endforeach; ?></div></fieldset>
<?php endforeach; endforeach; ?>
<?php foreach ($packages as $package): if (($package['package_type'] ?? '') === 'packed_meal'): ?><fieldset class="field field-wide package-options package-default-inclusion" data-package-options="<?= (int)$package['package_id'] ?>" hidden><legend>Rice · included</legend><p>Steamed rice is included in the packed lunch price and does not need to be selected.</p></fieldset><?php endif; endforeach; ?>
<fieldset class="field field-wide" data-alacarte hidden><legend>Choose food trays and quantities</legend><div class="package-choice-list"><?php foreach ($items as $item): ?><div class="package-choice-row"><span><strong><?= rc_e($item['name']) ?></strong><small><?= rc_e($item['description'] ?: $item['category']) ?> · <?= rc_e($unitLabels[$item['unit_type'] ?? 'tray_25_35pax'] ?? 'Each') ?> · <?= rc_money(rc_cents($item['price'])) ?></small><?php if (($item['unit_type'] ?? '') === 'tray_25_35pax'): ?><small data-tray-guidance>Choose tray quantity for your guest count.</small><?php endif; ?></span><label class="option-charge">Quantity<input name="items[<?= (int)$item['id'] ?>]" type="number" min="0" max="1000" step="1" value="<?= rc_e(isset($oldItems[$item['id']]) && is_scalar($oldItems[$item['id']]) ? (string)$oldItems[$item['id']] : '0') ?>" data-item-price="<?= rc_e($item['price']) ?>"></label></div><?php endforeach; ?></div></fieldset>
<div class="field"><label for="event-date">Event date</label><input class="input-field" id="event-date" name="event_date" type="date" min="<?= date('Y-m-d') ?>" value="<?= $oldValue('event_date') ?>" required></div><div class="field"><label for="event-start">Start time</label><input class="input-field" id="event-start" name="event_start_time" type="time" value="<?= $oldValue('event_start_time') ?>" required></div><div class="field"><label for="event-end">End time</label><input class="input-field" id="event-end" name="event_end_time" type="time" value="<?= $oldValue('event_end_time') ?>" required></div><div class="field"><label for="dining-time">Dining time</label><input class="input-field" id="dining-time" name="dining_time" type="time" value="<?= $oldValue('dining_time') ?>" required></div><div class="field"><label for="occasion">Occasion</label><input class="input-field" id="occasion" name="occasion" maxlength="100" placeholder="Birthday, wedding, etc." value="<?= $oldValue('occasion') ?>"></div><div class="field field-wide"><label for="venue">Venue and address</label><input class="input-field" id="venue" name="venue" maxlength="500" value="<?= $oldValue('venue') ?>" required></div><div class="field"><label for="motif">Motif / theme</label><input class="input-field" id="motif" name="motif" maxlength="160" value="<?= $oldValue('motif') ?>"></div><div class="field field-wide"><label for="requests">Special requests</label><textarea class="input-field" id="requests" name="special_requests" maxlength="5000"><?= $oldValue('special_requests') ?></textarea></div>
